// La herramienta recibe siempre lo mismo: de qué instancia viene y a quién
// atiende. NUNCA recibe el company_id — se deriva adentro de la base, igual
// que en el agente. Si una herramienta aceptara la empresa del payload,
// bastaría un error en el agente para leer los datos de otro cliente.
const b = $input.first().json.body || $input.first().json;
return [{ json: {
  instance: String(b.instance || ''),
  telefono: String(b.telefono || '').replace(/\D/g, ''),
}}];
